from pathlib import Path

p=Path('index.html')
s=p.read_text(encoding='utf-8')

# Add polished favorites styling once.
style_anchor='    .game-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:17px;padding:22px}\n'
style_new='''    .favorite-toolbar{display:flex;align-items:center;justify-content:flex-start;padding:12px 22px 0;min-height:50px}\n    .favorites-filter{height:38px;display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:0 14px;border:1px solid rgba(255,255,255,.30);border-radius:11px;background:rgba(3,52,146,.86);color:#fff;font-size:13px;font-weight:800;cursor:pointer;box-shadow:0 6px 16px rgba(0,30,100,.20),inset 0 1px 0 rgba(255,255,255,.18);transition:transform .16s ease,background .16s ease,box-shadow .16s ease,color .16s ease}\n    .favorites-filter:hover{transform:translateY(-2px);background:#063a92;box-shadow:0 9px 20px rgba(0,20,75,.24)}\n    .favorites-filter:active{transform:translateY(0);box-shadow:0 3px 9px rgba(0,20,75,.18)}\n    .favorites-filter:focus-visible{outline:3px solid rgba(255,255,255,.55);outline-offset:2px}\n    .favorites-filter.is-active{background:#fff;color:#06419f;border-color:#fff}\n    .favorite-count{min-width:22px;padding:2px 7px;border-radius:999px;background:rgba(255,255,255,.16);font-size:11px;line-height:18px;text-align:center}\n    .favorites-filter.is-active .favorite-count{background:rgba(6,65,159,.10)}\n    .favorite-badge{position:absolute;top:8px;right:8px;z-index:3;width:34px;height:34px;border:1px solid rgba(255,255,255,.72);border-radius:50%;background:rgba(7,27,68,.82);color:#fff;display:inline-flex;align-items:center;justify-content:center;font-size:19px;line-height:1;cursor:pointer;box-shadow:0 5px 13px rgba(0,0,0,.23);backdrop-filter:blur(3px);transition:transform .16s ease,background .16s ease,color .16s ease,box-shadow .16s ease}\n    .favorite-badge:hover{transform:scale(1.08);background:rgba(255,255,255,.96);color:#e2a400;box-shadow:0 7px 16px rgba(0,0,0,.23)}\n    .favorite-badge:focus-visible{outline:3px solid rgba(255,255,255,.8);outline-offset:2px}\n    .favorite-badge.is-favorite{background:#fff;color:#e2a400}\n    .favorite-empty{margin:10px 22px 22px;padding:30px 18px;border:1px dashed rgba(255,255,255,.28);border-radius:15px;color:rgba(255,255,255,.80);text-align:center;background:rgba(255,255,255,.07)}\n    .favorite-empty strong{display:block;color:#fff;font-size:17px;margin-bottom:5px}\n    @media(max-width:570px){.favorite-toolbar{padding:10px 14px 0}.favorite-empty{margin-left:14px;margin-right:14px}}\n'''
if '.favorites-filter{' not in s:
    if style_anchor not in s: raise SystemExit('game grid style anchor not found')
    s=s.replace(style_anchor,style_new+style_anchor,1)

# Insert favorites controls immediately before the live game grid.
if 'id="favoritesFilter"' not in s:
    grid_anchor='      <div id="gameGrid" class="game-grid"></div>'
    toolbar='''      <div id="favoriteToolbar" class="favorite-toolbar" aria-label="Favorite games controls">\n        <button id="favoritesFilter" class="favorites-filter" type="button" aria-pressed="false"><span aria-hidden="true">★</span><span>Favorites</span><span id="favoriteCount" class="favorite-count">0</span></button>\n      </div>\n      <div id="favoriteEmpty" class="favorite-empty" hidden><strong>No favorites yet</strong><span>Press the ★ on any game to save it here.</span></div>\n'''
    if grid_anchor not in s: raise SystemExit('game grid element not found')
    s=s.replace(grid_anchor,toolbar+grid_anchor,1)

# Add the client-side favorites system once. It works with the existing dynamic legacy game loader.
marker='  /* Personalized recommendation carousel */\n'
if '/* Local favorites */' not in s:
    fav='''  /* Local favorites */\n  (function(){\n    const grid=document.getElementById('gameGrid');\n    const filter=document.getElementById('favoritesFilter');\n    const countEl=document.getElementById('favoriteCount');\n    const empty=document.getElementById('favoriteEmpty');\n    if(!grid||!filter||!countEl||!empty)return;\n\n    const KEY='ubg_favorites_v2';\n    const read=()=>{try{const v=JSON.parse(localStorage.getItem(KEY)||'[]');return Array.isArray(v)?v:[]}catch(_){return[]}};\n    const write=v=>{try{localStorage.setItem(KEY,JSON.stringify(v));}catch(_){} };\n    const clean=s=>(s||'').toString().replace(/\\s+/g,' ').trim();\n    const norm=s=>clean(s).toLowerCase();\n    let favoriteMode=false;\n\n    function cardTitle(card){return clean(card.querySelector('h3')?.textContent||card.querySelector('img')?.alt||'Game');}\n    function favoriteKey(card){\n      const title=cardTitle(card);\n      const src=card.querySelector('img')?.currentSrc||card.querySelector('img')?.src||'';\n      return norm(title)+'|'+src;\n    }\n    function cards(){return Array.from(grid.querySelectorAll(':scope > .game-card'));}\n    function decorate(card){\n      if(card.querySelector(':scope > .favorite-badge'))return;\n      const btn=document.createElement('button');\n      btn.type='button';\n      btn.className='favorite-badge';\n      btn.textContent='★';\n      btn.setAttribute('aria-label','Add '+cardTitle(card)+' to favorites');\n      btn.title='Add to favorites';\n      btn.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();toggle(card);});\n      card.appendChild(btn);\n    }\n    function update(){\n      const set=new Set(read());\n      const all=cards();\n      all.forEach(card=>{\n        decorate(card);\n        const fav=set.has(favoriteKey(card));\n        const btn=card.querySelector(':scope > .favorite-badge');\n        btn.classList.toggle('is-favorite',fav);\n        btn.setAttribute('aria-label',fav?'Remove '+cardTitle(card)+' from favorites':'Add '+cardTitle(card)+' to favorites');\n        btn.title=fav?'Remove from favorites':'Add to favorites';\n        card.dataset.favorite=fav?'true':'false';\n      });\n      const n=all.filter(card=>set.has(favoriteKey(card))).length;\n      countEl.textContent=String(n);\n      filter.classList.toggle('is-active',favoriteMode);\n      filter.setAttribute('aria-pressed',String(favoriteMode));\n      applyVisibility();\n    }\n    function applyVisibility(){\n      const set=new Set(read());\n      const query=(document.getElementById('searchBar')?.value||'').trim();\n      const all=cards();\n      all.forEach(card=>{\n        const fav=set.has(favoriteKey(card));\n        const searchMatch=!query || typeof rank!=='function' || rank(cardTitle(card),query)<99;\n        card.style.display=(searchMatch && (!favoriteMode||fav))?'':'none';\n      });\n      empty.hidden=!(favoriteMode && all.length && all.every(card=>card.style.display==='none'));\n    }\n    function toggle(card){\n      const key=favoriteKey(card);\n      const next=read();\n      const index=next.indexOf(key);\n      if(index>=0)next.splice(index,1);else next.unshift(key);\n      write(next.slice(0,300));\n      update();\n    }\n    filter.addEventListener('click',()=>{favoriteMode=!favoriteMode;update();});\n    new MutationObserver(update).observe(grid,{childList:true});\n    window.addEventListener('storage',e=>{if(e.key===KEY)update();});\n    update();\n  })();\n\n'''
    if marker not in s: raise SystemExit('recommendation marker not found')
    s=s.replace(marker,fav+marker,1)

p.write_text(s,encoding='utf-8')
